import{_ as t,g as a,e as o,a4 as r}from"./chunks/framework.CEYJDsBW.js";const h=JSON.parse('{"title":"Block Tags, Layout, and Formulas","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/packs/blocks.md","filePath":"en/ageratum/26.1/packs/blocks.md"}'),n={name:"en/ageratum/26.1/packs/blocks.md"};function s(d,e,i,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="block-tags-layout-and-formulas" tabindex="-1">Block Tags, Layout, and Formulas <a class="header-anchor" href="#block-tags-layout-and-formulas" aria-label="Permalink to &quot;Block Tags, Layout, and Formulas&quot;">​</a></h1><p>Callout boxes and row layouts can be nested. Opening and closing tags each occupy their own line, while single tags without body content use self-closing form. The two materials below are centered on the same row.</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;tip&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Prepare materials before repairing.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/tip&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;row direction=&quot;horizontal&quot; halign=&quot;center&quot; valign=&quot;center&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;item id=&quot;minecraft:iron_ingot&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;item id=&quot;minecraft:iron_pickaxe&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/row&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;latex formula=&quot;a^2+b^2=c^2&quot; dpi=&quot;150&quot; color=&quot;#29405B&quot; center=&quot;true&quot;/&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tag or Parameter</th><th>Type</th><th>Requirements &amp; Default Behavior</th></tr></thead><tbody><tr><td><code>info</code>, <code>tip</code>, <code>warning</code>, <code>danger</code></td><td>Paired block tags</td><td>Accept parsed Markdown child content. No required attributes.</td></tr><tr><td><code>row.direction</code> (alias <code>dir</code>)</td><td>String</td><td>Optional, default <code>horizontal</code>. Vertical layout accepts <code>v</code>, <code>vertical</code>, <code>column</code>, <code>col</code>.</td></tr><tr><td><code>row.halign</code></td><td>String</td><td>Optional, default <code>left</code>. Accepts <code>center</code> or <code>right</code>; aliases fall back in order <code>alignX</code>, <code>xAlign</code>, <code>align</code>.</td></tr><tr><td><code>row.valign</code></td><td>String</td><td>Optional, default <code>top</code>. Controls <code>center</code> or <code>bottom</code> alignment within a horizontal row; aliases <code>alignY</code>, <code>yAlign</code>.</td></tr><tr><td><code>latex.formula</code></td><td>String</td><td>At least one of this or a non-empty block body must be provided. Attribute takes precedence.</td></tr><tr><td><code>latex.dpi</code></td><td>Integer string</td><td>Optional, default <code>150</code>, clamped to <code>72</code>–<code>600</code>.</td></tr><tr><td><code>latex.scale</code></td><td>Numeric string</td><td>Optional. Default parsed value is <code>0.1</code>; actual display is also subject to minimum readable height, layout space, and <code>0.5</code>–<code>2.0</code> scaling limits.</td></tr><tr><td><code>latex.color</code></td><td>Hex color string</td><td>Optional, default black; accepts 6-digit hex with or without <code>#</code>.</td></tr><tr><td><code>latex.center</code></td><td>Boolean string</td><td>Optional, default <code>true</code>.</td></tr></tbody></table><p>The formula component requests images from CodeCogs. When unreachable, it displays a loading or failure notice. To show fixed formulas in offline modpacks, you can also ship formula images with the resource pack. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDLatexComponent.java" target="_blank" rel="noreferrer">LaTeX component</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/component/extend/MDRowComponent.java" target="_blank" rel="noreferrer">Row layout</a></p><h2 id="how-parameters-are-read" tabindex="-1">How Parameters Are Read <a class="header-anchor" href="#how-parameters-are-read" aria-label="Permalink to &quot;How Parameters Are Read&quot;">​</a></h2><p>Tag attributes use <code>key=value</code>. Keys support letters, digits, underscores, dots, and hyphens. Values may be unquoted, or wrapped in single or double quotes when containing spaces. Duplicate keys take the last value. Wrapping with outer single quotes preserves double quotes inside a JSON object verbatim. This uses a key-value parser; components only invoke JSON or SNBT decoders on their corresponding fields, and general HOCON objects have no parsing entrypoint.</p><p><code>::: tip</code> with a standalone closing <code>:::</code> can also be used for callout boxes. Colon syntax passes the trailing text as raw parameters to the factory, and the built-in <code>row</code> parses that text separately. Built-in components that need structured attributes such as <code>id</code> should use tag syntax. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/ExtensionParamParser.java" target="_blank" rel="noreferrer">Attribute parser</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/MarkdownParser.java" target="_blank" rel="noreferrer">Block parser</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/registries/BuiltinExtensionComponents.java" target="_blank" rel="noreferrer">Factory registry</a></p>`,8)])])}const g=t(n,[["render",s]]);export{h as __pageData,g as default};
